tool_input.command:
node --input-type=module -e '
import { createReviewStore } from "./benchmark/fixtures/T5-review-queue/review-store.mjs";
import { createReviewApi } from "./benchmark/fixtures/T5-review-queue/review-api.mjs";
const s = createReviewStore({ now: () => "2026-01-01T00:00:00.000Z" });
const h = createReviewApi(s);
const p = (b) => h({ method: "POST", url: "/api/reviews", body: b });
const ok = { runId: "run-abc", decision: "approve", reviewer: "Ada", note: "" };

console.log("runId boundary run-ab:", p({...ok, runId:"run-ab"}).status, "run-abc:", p({...ok,runId:"run-abc"}).status);
console.log("64+ runId:", p({...ok, runId: "run-" + "a".repeat(64)}).status, "63:", p({...ok, runId:"run-"+"a".repeat(63)}).status);
console.log("note 240:", p({...ok, decision:"reject", note:"x".repeat(240)}).status, "241:", p({...ok, decision:"reject", note:"x".repeat(241)}).status);
console.log("reviewer 1/2/40/41:", p({...ok,reviewer:"A"}).status, p({...ok,reviewer:"Ad"}).status, p({...ok,reviewer:"a".repeat(40)}).status, p({...ok,reviewer:"a".repeat(41)}).status);

// response isolation from store
const r = p(ok);
r.body.review.reviewer = "HACKED";
console.log("store isolation after mutating response:", s.get("run-abc").reviewer);
const g = h({ method:"GET", url:"/api/reviews" });
g.body.reviews.push({ runId:"injected" }); g.body.summary.total = 99;
console.log("after mutating GET body:", s.list().length, h({method:"GET",url:"/api/reviews"}).body.summary);

// header isolation
const a405 = h({ method:"DELETE", url:"/api/reviews" });
console.log("405 headers:", JSON.stringify(a405.headers), "keys:", Object.keys(a405));
console.log("empty decision query:", JSON.stringify(h({method:"GET",url:"/api/reviews?decision="}).body));
console.log("trailing slash collection:", h({method:"GET",url:"/api/reviews/"}).status);
console.log("bad url:", JSON.stringify(h({method:"GET",url:"http://"}).body));
console.log("no url:", JSON.stringify(h({method:"GET"}).body));
console.log("proto key:", JSON.stringify(p({...ok, __proto__: 1}).body));
'
